unsafe fn Mask_calcRunLengthV(
    mut width: c_int,
    mut frame: *mut c_uchar,
    mut runLength: *mut c_int,
) -> c_int {
    let first = unsafe { *frame }; // SAFETY: caller provides valid `frame` for at least one readable element, as required by the original function.
    let mut head: c_int;
    if (first as c_int & 1) != 0 {
        unsafe { *runLength = -1 }; // SAFETY: caller provides valid `runLength` for writes performed by the original function.
        head = 1;
    } else {
        head = 0;
    }
    unsafe { *runLength.add(head as usize) = 1 }; // SAFETY: same preconditions as the original function; index written matches original behavior.

    let mut prev_bit = first & 1;
    let mut i: c_int = 1;
    while i < width {
        let p = unsafe { frame.offset((i * width) as isize) }; // SAFETY: pointer arithmetic matches the original function's accessed locations.
        let cur = unsafe { *p }; // SAFETY: caller guarantees the computed location is readable, as in the original function.
        let cur_bit = cur & 1;
        if cur_bit != prev_bit {
            head += 1;
            unsafe { *runLength.add(head as usize) = 1 }; // SAFETY: caller guarantees `runLength` is writable for all indices used by the original function.
            prev_bit = cur_bit;
        } else {
            let slot = unsafe { runLength.add(head as usize) }; // SAFETY: same writable index as in the original function.
            unsafe { *slot += 1 }; // SAFETY: `slot` points to a valid writable run-length entry under the original function's preconditions.
        }
        i += 1;
    }
    head + 1
}

